import asyncio, json, re, sys
from pathlib import Path
sys.path.insert(0, str(Path('.').resolve() / 'libs'))
from claude_bundles.chat_cowork_mode import select_compose_mode
from claude_bundles.compose_attest import compose_mode_fingerprint
from claude_bundles.skills_ui_panel import DEFAULT_CDP_URL, connect_cdp

CHIP = "[data-ulg-trace-chip='1']"
MARK = r"""() => {
  const re = /^(auto|manual|skip)$/i;
  let best = null;
  for (const el of document.querySelectorAll('button, [role="button"]')) {
    const text = (el.innerText || '').trim();
    if (!re.test(text) || !el.offsetParent) continue;
    const r = el.getBoundingClientRect();
    if (r.width < 28 || r.width > 140 || r.height < 16 || r.height > 48) continue;
    if (!best || r.width < best.w) best = {el, w: r.width};
  }
  if (!best) return false;
  best.el.setAttribute('data-ulg-trace-chip', '1');
  return {
    expanded: best.el.getAttribute('aria-expanded'),
    text: (best.el.innerText || '').trim(),
  };
}"""

SNAP = r"""() => {
  const chip = document.querySelector('[data-ulg-trace-chip="1"]');
  const rows = [...document.querySelectorAll('[role=menuitemradio]')].map(el => ({
    t: (el.innerText||'').replace(/\s+/g,' ').trim().slice(0, 40),
    checked: el.getAttribute('aria-checked'),
    highlighted: el.hasAttribute('data-highlighted'),
  }));
  const dialogs = [...document.querySelectorAll('[role=dialog], [role=alertdialog]')].map(el => ({
    text: (el.innerText||'').replace(/\s+/g,' ').trim().slice(0, 120),
    hidden: el.hidden || el.getAttribute('aria-hidden'),
  }));
  const buttons = [...document.querySelectorAll('button')].map(el => (el.innerText||'').trim().replace(/\s+/g,' ').slice(0, 24)).filter(t => /auto|manual|skip|confirm|allow|continue/i.test(t)).slice(0, 12);
  return {
    chip: chip ? {
      text: (chip.innerText||'').trim(),
      expanded: chip.getAttribute('aria-expanded'),
      controls: chip.getAttribute('aria-controls'),
    } : None,
    rows,
    dialogs,
    buttons,
  };
}"""

async def label(page):
    fp = await compose_mode_fingerprint(page)
    return (fp.get('approval') or {}).get('text')

async def fresh(page):
    await page.goto('https://claude.ai/new', wait_until='domcontentloaded', timeout=30000)
    mode = await select_compose_mode(page, 'cowork')
    mark = await page.evaluate(MARK)
    return {'mode': mode.get('step'), 'mark': mark}

async def main():
    pw, _b, ctx, _ = await connect_cdp(DEFAULT_CDP_URL)
    page = await ctx.new_page()
    out = {}
    try:
        out['fresh'] = await fresh(page)
        # Trusted pointer open only — menu must start closed.
        await page.locator(CHIP).click(timeout=8000)
        await page.wait_for_timeout(500)
        out['after_trusted_open'] = await page.evaluate(SNAP)
        loc = page.get_by_role('menuitemradio', name=re.compile(r'Skip all approvals', re.I))
        out['skip_count'] = await loc.count()
        if await loc.count():
            await loc.first.hover()
            await page.wait_for_timeout(150)
            await loc.first.click(timeout=5000)
            await page.wait_for_timeout(600)
        out['after_trusted_row'] = await page.evaluate(SNAP)
        out['label_trusted'] = await label(page)

        # Second attempt: trusted open + Space on highlighted skip
        await fresh(page)
        await page.locator(CHIP).click(timeout=8000)
        await page.wait_for_timeout(400)
        # highlight starts on Manual; two ArrowDown to Skip, then Space
        await page.keyboard.press('ArrowDown')
        await page.keyboard.press('ArrowDown')
        await page.wait_for_timeout(100)
        out['before_space'] = await page.evaluate(SNAP)
        await page.keyboard.press('Space')
        await page.wait_for_timeout(500)
        out['after_space'] = await page.evaluate(SNAP)
        out['label_space'] = await label(page)
        await page.keyboard.press('Escape')
        print(json.dumps(out, indent=2, default=str))
    finally:
        await page.close()
        await pw.stop()

asyncio.run(main())
